+  "ddp_test_source": "import os, sys, tempfile, unittest, socket, subprocess\nfrom pathlib import Path\nimport torch\nimport torch.distributed as dist\nimport torch.multiprocessing as mp\n\nTREE = Path('/fs04/ar57/wenyu/GeneRec/stage2_RQ-VAE/TIGER_c117_global_sinkhorn_poincare').resolve()\nsys.path.insert(0, str(TREE))\n\ndef _rank_worker(rank, world, init_file, out_file):\n    sys.path.insert(0, str(TREE))\n    dist.init_process_group('gloo', init_method='file://' + init_file, rank=rank, world_size=world)\n    torch.manual_seed(991)\n    from model import RQVAE\n    import train_rqvae as trainer\n    cfg = trainer._tokenizer_config()\n    model = RQVAE(cfg, in_dim=8)\n    model = torch.nn.parallel.DistributedDataParallel(model)\n    # Distinct rank-local minibatches, same actual source-tree model and loss path.\n    x = torch.randn(4, 8) + float(rank)\n    model.module.init_codebook(torch.cat([x, x + .1], dim=0))\n    model.module.refresh_assignment(torch.cat([x, x + .1], dim=0))\n    loss, *_ = model(x, torch.arange(4))\n    loss.backward()\n    opt = torch.optim.SGD(model.parameters(), lr=.01)\n    opt.step()\n    local = torch.cat([p.detach().reshape(-1) for p in model.module.parameters()]).clone()\n    gathered = [torch.empty_like(local) for _ in range(world)]\n    dist.all_gather(gathered, local)\n    torch.save([v.cpu() for v in gathered], out_file + str(rank))\n    dist.destroy_process_group()\n\nclass TestRealDDP(unittest.TestCase):\n    def test_two_real_ranks_gather_independent_updated_parameters(self):\n        self.assertTrue(torch.distributed.is_available())\n        with tempfile.TemporaryDirectory() as d:\n            init = str(Path(d) / 'init')\n            out = str(Path(d) / 'rank')\n            mp.spawn(_rank_worker, args=(2, init, out), nprocs=2, join=True)\n            a, b = torch.load(out+'0', weights_only=True), torch.load(out+'1', weights_only=True)\n            self.assertEqual(len(a), 2)\n            self.assertTrue(torch.equal(a[0], a[1]))\n            self.assertTrue(torch.equal(b[0], b[1]))\n            self.assertTrue(torch.allclose(a[0], b[0], atol=1e-6, rtol=1e-6))\n            self.assertFalse(torch.equal(a[0], torch.zeros_like(a[0])))\n",
